import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { I18nProvider, useI18n } from './lib/i18n.jsx'
import { initialHazards, parseBuildingText } from './lib/validate.js'
import { findRoute } from './lib/route.js'
import Header from './components/Header.jsx'
import EmptyState from './components/EmptyState.jsx'
import MapView from './components/MapView.jsx'
import ModeSwitch from './components/ModeSwitch.jsx'
import Legend from './components/Legend.jsx'
import RoutePanel from './components/RoutePanel.jsx'
import HazardPanel from './components/HazardPanel.jsx'
import ImportErrors from './components/ImportErrors.jsx'
import Toast from './components/Toast.jsx'
import './map.css'

const SAVE_KEY = 'smart-escape.session'

// Restore the last session (file text + hazards + start) from localStorage, if valid.
function loadSaved() {
  try {
    const saved = JSON.parse(localStorage.getItem(SAVE_KEY))
    const res = parseBuildingText(saved.text)
    if (!res.ok) return null
    const { graph } = res
    const keep = (ids, has) => new Set((ids ?? []).filter(has))
    return {
      text: saved.text,
      graph,
      hazards: {
        blockedNodes: keep(saved.hazards.blockedNodes, (id) => graph.nodeById.get(id)?.type !== 'exit' && graph.nodeById.has(id)),
        blockedEdges: keep(saved.hazards.blockedEdges, (id) => graph.edgeById.has(id)),
        closedExits: keep(saved.hazards.closedExits, (id) => graph.nodeById.get(id)?.type === 'exit'),
      },
      startId: graph.nodeById.get(saved.startId)?.type !== 'exit' && graph.nodeById.has(saved.startId) ? saved.startId : null,
    }
  } catch {
    return null
  }
}

export default function App() {
  return (
    <I18nProvider>
      <Shell />
    </I18nProvider>
  )
}

function Shell() {
  const { t } = useI18n()
  const [restored] = useState(loadSaved)
  const [text, setText] = useState(restored?.text ?? null)
  const [graph, setGraph] = useState(restored?.graph ?? null)
  const [hazards, setHazards] = useState(restored?.hazards ?? null)
  const [startId, setStartId] = useState(restored?.startId ?? null)
  const [mode, setMode] = useState('start')
  const [errors, setErrors] = useState(null)
  const [toast, setToast] = useState(null)
  const [highlightId, setHighlightId] = useState(null)
  const [dragging, setDragging] = useState(false)
  const [reroute, setReroute] = useState(null)
  const [ghostPath, setGhostPath] = useState(null)
  const fileRef = useRef(null)
  const lastRoute = useRef(null)

  // The route is a pure function of graph + hazards + start, so it is
  // recalculated immediately on every change.
  const result = useMemo(() => findRoute(graph, hazards, startId), [graph, hazards, startId])

  // Toasts keep the i18n key so they follow a language switch.
  const notify = useCallback((key, params) => setToast({ id: Date.now(), key, params }), [])

  useEffect(() => {
    if (!toast) return
    const timer = setTimeout(() => setToast(null), 2400)
    return () => clearTimeout(timer)
  }, [toast])

  // Detect reroutes (same start, different route) to show the old route fading
  // out and the cost change badge.
  useEffect(() => {
    const prev = lastRoute.current
    const sig = result.status === 'ok' ? result.path.join('>') : result.status
    lastRoute.current = { graph, startId: result.startId, sig, result }
    if (!prev || prev.graph !== graph || prev.startId !== result.startId) {
      setReroute(null)
      setGhostPath(null)
      return
    }
    if (prev.sig === sig) return
    setGhostPath(prev.result.status === 'ok' ? prev.result.path : null)
    setReroute(
      prev.result.status === 'ok' && result.status === 'ok' ? { from: prev.result.cost, to: result.cost } : null,
    )
  }, [graph, result])

  // Save progress locally (browser storage only).
  useEffect(() => {
    if (!text || !hazards) return
    try {
      localStorage.setItem(
        SAVE_KEY,
        JSON.stringify({
          text,
          startId,
          hazards: {
            blockedNodes: [...hazards.blockedNodes],
            blockedEdges: [...hazards.blockedEdges],
            closedExits: [...hazards.closedExits],
          },
        }),
      )
    } catch {
      /* storage unavailable */
    }
  }, [text, hazards, startId])

  const importText = useCallback(
    (raw) => {
      const res = parseBuildingText(raw)
      if (!res.ok) {
        setErrors(res.errors)
        return
      }
      setErrors(null)
      setText(raw)
      setGraph(res.graph)
      setHazards(initialHazards(res.graph))
      setStartId(null)
      setMode('start')
      notify('msg.loaded', { name: res.graph.building })
    },
    [notify],
  )

  const onFile = useCallback(
    async (file) => {
      if (!file) return
      try {
        importText(await file.text())
      } catch {
        setErrors([{ code: 'read' }])
      }
    },
    [importText],
  )

  const loadSample = useCallback(async () => {
    try {
      const res = await fetch(`${import.meta.env.BASE_URL}building.json`)
      importText(await res.text())
    } catch {
      setErrors([{ code: 'read' }])
    }
  }, [importText])

  const toggle = (key, id) =>
    setHazards((h) => {
      const next = new Set(h[key])
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return { ...h, [key]: next }
    })

  const setStart = (id) => {
    const node = graph.nodeById.get(id)
    if (!node) return
    if (node.type === 'exit') return notify('msg.exitNotStart')
    if (hazards.blockedNodes.has(id)) return notify('msg.blockedNotStart')
    setStartId(id)
  }

  const onNodeClick = (id) => {
    const node = graph.nodeById.get(id)
    if (mode === 'start') return setStart(id)
    toggle(node.type === 'exit' ? 'closedExits' : 'blockedNodes', id)
  }

  const reset = useCallback(() => {
    if (!graph) return
    setHazards(initialHazards(graph))
    notify('msg.reset')
  }, [graph, notify])

  // Keyboard shortcuts: S = set-start mode, H = hazard mode, R = reset.
  useEffect(() => {
    const onKey = (e) => {
      if (!graph || e.metaKey || e.ctrlKey || e.altKey) return
      if (e.target.closest?.('input, select, textarea')) return
      const key = e.key.toLowerCase()
      if (key === 's') setMode('start')
      else if (key === 'h') setMode('hazard')
      else if (key === 'r') reset()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [graph, reset])

  const dragProps = {
    onDragOver: (e) => {
      e.preventDefault()
      setDragging(true)
    },
    onDragLeave: (e) => {
      if (!e.currentTarget.contains(e.relatedTarget)) setDragging(false)
    },
    onDrop: (e) => {
      e.preventDefault()
      setDragging(false)
      onFile(e.dataTransfer.files?.[0])
    },
  }

  return (
    <div className={`app${dragging ? ' is-dragging' : ''}`} {...dragProps}>
      <Header
        building={graph?.building}
        hasGraph={Boolean(graph)}
        onImport={() => fileRef.current?.click()}
        onLoadSample={loadSample}
      />
      <input
        ref={fileRef}
        type="file"
        accept=".json,application/json"
        hidden
        onChange={(e) => {
          onFile(e.target.files?.[0])
          e.target.value = ''
        }}
      />

      {errors && <ImportErrors errors={errors} onDismiss={() => setErrors(null)} />}

      {graph ? (
        <main className="workspace">
          <section className="map-stage">
            <div className="stage-bar stage-bar--top">
              <ModeSwitch mode={mode} onChange={setMode} />
            </div>
            <div className="map-area">
              <MapView
                graph={graph}
                hazards={hazards}
                result={result}
                ghostPath={ghostPath}
                highlightId={highlightId}
                onNodeClick={onNodeClick}
                onEdgeClick={(id) => toggle('blockedEdges', id)}
              />
            </div>
            <div className="stage-bar stage-bar--bottom">
              <Legend />
            </div>
          </section>
          <aside className="sidebar">
            <RoutePanel result={result} graph={graph} reroute={reroute} onHoverNode={setHighlightId} />
            <HazardPanel
              graph={graph}
              hazards={hazards}
              startId={startId}
              onSetStart={setStart}
              onToggleNode={(id) => toggle('blockedNodes', id)}
              onToggleEdge={(id) => toggle('blockedEdges', id)}
              onToggleExit={(id) => toggle('closedExits', id)}
              onReset={reset}
            />
          </aside>
        </main>
      ) : (
        <EmptyState onFile={onFile} onLoadSample={loadSample} dragging={dragging} />
      )}

      <footer className="footer">{t('app.disclaimer')}</footer>
      <Toast message={toast && { id: toast.id, text: t(toast.key, toast.params) }} />
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { useI18n } from '../lib/i18n.jsx'
import {
  CheckCircle2,
  OctagonX,
  TriangleAlert,
  MousePointerClick,
  Shuffle,
  ChevronRight,
} from 'lucide-react'

function useTweenedNumber(target, duration = 400) {
  const [current, setCurrent] = useState(target)
  const prevTargetRef = useRef(target)

  useEffect(() => {
    const startVal = prevTargetRef.current ?? target
    prevTargetRef.current = target

    if (startVal === target) {
      return
    }

    let startTime = null
    let animId = null

    const step = (timestamp) => {
      if (target == null) {
        setCurrent(null)
        return
      }

      if (
        typeof window !== 'undefined' &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches
      ) {
        setCurrent(target)
        return
      }

      if (!startTime) startTime = timestamp
      const elapsed = timestamp - startTime
      const progress = Math.min(elapsed / duration, 1)
      // Ease out cubic
      const ease = 1 - Math.pow(1 - progress, 3)
      const val = Math.round(startVal + (target - startVal) * ease)
      setCurrent(val)

      if (progress < 1) {
        animId = requestAnimationFrame(step)
      } else {
        setCurrent(target)
      }
    }

    animId = requestAnimationFrame(step)
    return () => {
      if (animId) cancelAnimationFrame(animId)
    }
  }, [target, duration])

  return current
}

function computeStepsWithTotals(steps) {
  let running = 0
  return steps.map((step) => {
    running += step.cost
    return { ...step, total: running }
  })
}

export default function RoutePanel({ result, graph, reroute, onHoverNode }) {
  const { t, num } = useI18n()
  const status = result?.status ?? 'idle'
  const isOk = status === 'ok'
  const displayedCost = useTweenedNumber(isOk ? result?.cost : null)

  const exitNode = isOk && result?.exitId && graph?.nodeById ? graph.nodeById.get(result.exitId) : null
  const exitLabel = exitNode?.label || ''

  // Step-by-step with running cumulative cost
  const stepsWithTotal = isOk && result?.steps ? computeStepsWithTotals(result.steps) : []

  // Has reroute diff?
  const hasReroute = Boolean(reroute && reroute.from !== reroute.to)
  const costIncreased = hasReroute && reroute.to > reroute.from
  const diffCost = hasReroute ? reroute.to - reroute.from : 0

  return (
    <div className={`card route-card route-card--${status}`}>
      {/* Top Status Banner */}
      <div className={`route-card__status-banner route-card__status-banner--${status}`}>
        {status === 'ok' && (
          <>
            <CheckCircle2 size={18} aria-hidden="true" />
            <div className="route-card__status-info">
              <span className="route-card__status-title">{t('status.ok')}</span>
            </div>
          </>
        )}

        {status === 'no-route' && (
          <>
            <OctagonX size={18} aria-hidden="true" />
            <div className="route-card__status-info">
              <span className="route-card__status-title">{t('status.noRoute')}</span>
              <p className="route-card__status-hint">{t('status.noRouteHint')}</p>
            </div>
          </>
        )}

        {status === 'start-blocked' && (
          <>
            <TriangleAlert size={18} aria-hidden="true" />
            <div className="route-card__status-info">
              <span className="route-card__status-title">{t('status.startBlocked')}</span>
              <p className="route-card__status-hint">{t('status.startBlockedHint')}</p>
            </div>
          </>
        )}

        {status === 'idle' && (
          <>
            <MousePointerClick size={18} aria-hidden="true" />
            <div className="route-card__status-info">
              <span className="route-card__status-title">{t('status.idle')}</span>
              <p className="route-card__status-hint">{t('status.idleHint')}</p>
            </div>
          </>
        )}
      </div>

      {/* Body content cross-fades on status change */}
      <div key={status} className="route-card__body-transition">
        {isOk && (
          <>
            {/* Evacuate via Exit + Big Cost */}
            <div className="route-card__evac-row">
              <div className="route-card__evac-left">
                <span className="section-title">{t('route.evacuateVia')}</span>
                <span className="route-card__exit-id">{result.exitId}</span>
                {exitLabel && <span className="route-card__exit-label">{exitLabel}</span>}
              </div>

              <div className="route-card__cost-group">
                <span className="section-title">{t('route.cost')}</span>
                <span className="route-card__cost-value">
                  {num(displayedCost ?? result.cost)}
                </span>
              </div>
            </div>

            {/* Rerouted Badge */}
            {hasReroute && (
              <div className="route-card__reroute-wrap">
                <span className={`badge ${costIncreased ? 'badge--warn' : 'badge--exit'}`}>
                  <Shuffle size={12} aria-hidden="true" />
                  <span>
                    {t('route.rerouted')}{' '}
                    {num(reroute.from)} → {num(reroute.to)} (
                    {diffCost > 0 ? '+' : ''}
                    {num(diffCost)})
                  </span>
                </span>
              </div>
            )}

            {/* Route Chips */}
            {result.path && result.path.length > 0 && (
              <div className="route-card__path-section">
                <span className="section-title">{t('route.path')}</span>
                <div className="route-card__chips" key={result.path.join('>')}>
                  {result.path.map((nodeId, idx) => {
                    const isStart = idx === 0
                    const isExit = idx === result.path.length - 1
                    const chipClass = isStart
                      ? 'route-chip route-chip--start'
                      : isExit
                        ? 'route-chip route-chip--exit'
                        : 'route-chip'

                    return (
                      <span
                        key={nodeId}
                        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
                      >
                        <button
                          type="button"
                          className={chipClass}
                          style={{ animationDelay: `${idx * 30}ms` }}
                          onMouseEnter={() => onHoverNode?.(nodeId)}
                          onMouseLeave={() => onHoverNode?.(null)}
                          onFocus={() => onHoverNode?.(nodeId)}
                          onBlur={() => onHoverNode?.(null)}
                        >
                          {nodeId}
                        </button>
                        {!isExit && (
                          <ChevronRight
                            size={14}
                            className="route-card__path-sep"
                            aria-hidden="true"
                          />
                        )}
                      </span>
                    )
                  })}
                </div>
              </div>
            )}

            {/* Step-by-step corridor list */}
            {stepsWithTotal.length > 0 && (
              <details open className="route-card__details">
                <summary className="route-card__summary">
                  <span>{t('route.steps')}</span>
                  <span className="route-card__step-count">
                    {t('route.stepsCount', { n: stepsWithTotal.length })}
                  </span>
                </summary>
                <ol className="route-card__step-list">
                  {stepsWithTotal.map((step, idx) => (
                    <li
                      key={`${step.from}-${step.to}-${step.edgeId}-${idx}`}
                      className="route-step"
                    >
                      <span className="route-step__endpoints">
                        {step.from} → {step.to}
                      </span>
                      <span className="route-step__corridor">{step.edgeId}</span>
                      <div className="route-step__costs">
                        <span className="route-step__cost">+{num(step.cost)}</span>
                        <span className="route-step__total">{num(step.total)}</span>
                      </div>
                    </li>
                  ))}
                </ol>
              </details>
            )}

            {/* Alternatives */}
            <div className="route-card__alts-section">
              <span className="section-title">{t('route.alternatives')}</span>
              {result.alternatives && result.alternatives.length > 0 ? (
                <div className="route-card__alts-list">
                  {result.alternatives.map((alt) => (
                    <div key={alt.exitId} className="route-alt">
                      <div className="route-alt__left">
                        <span className="chip chip--exit-outline">{alt.exitId}</span>
                        <span className="route-alt__label">
                          {graph?.nodeById?.get(alt.exitId)?.label ?? alt.exitId}
                        </span>
                      </div>
                      <span className="route-alt__cost">{num(alt.cost)}</span>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="route-card__no-alts">{t('route.noAlternatives')}</p>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

// Validates a parsed building.json object against the Smart Escape schema.
// Returns { ok: true, graph } or { ok: false, errors: [{ code, params }] }.
// Error codes map to i18n keys `err.<code>` so messages can be shown in both languages.

const NODE_TYPES = new Set(['room', 'junction', 'exit'])
const STATE_FIELDS = ['blocked_nodes', 'blocked_edges', 'closed_exits']

const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v)
const isNonEmptyString = (v) => typeof v === 'string' && v.trim() !== ''

export function parseBuildingText(text) {
  let data
  try {
    data = JSON.parse(text.replace(/^\uFEFF/, '')) // tolerate a UTF-8 byte-order mark
  } catch {
    return { ok: false, errors: [{ code: 'json' }] }
  }
  return validateBuilding(data)
}

export function validateBuilding(data) {
  const errors = []
  const err = (code, params) => errors.push({ code, params })

  if (!isObject(data)) return { ok: false, errors: [{ code: 'root' }] }

  if (!isNonEmptyString(data.building)) err('building')

  // --- nodes ---
  const nodes = []
  const nodeById = new Map()
  if (!Array.isArray(data.nodes)) {
    err('nodesArray')
  } else {
    if (data.nodes.length < 2 || data.nodes.length > 60) err('nodesCount', { n: data.nodes.length })
    data.nodes.forEach((n, i) => {
      if (!isObject(n)) return err('nodeObj', { i })
      if (!isNonEmptyString(n.id)) return err('nodeId', { i })
      if (nodeById.has(n.id)) return err('nodeDupId', { id: n.id })
      const before = errors.length
      if (!isNonEmptyString(n.label)) err('nodeLabel', { id: n.id })
      if (!NODE_TYPES.has(n.type)) err('nodeType', { id: n.id, type: String(n.type) })
      if (!Number.isFinite(n.x) || !Number.isFinite(n.y)) err('nodeCoord', { id: n.id })
      const node = { id: n.id, label: n.label, type: n.type, x: n.x, y: n.y }
      nodeById.set(n.id, node) // registered even if invalid, so edges don't report it as unknown
      if (errors.length === before) nodes.push(node)
    })
    if (!data.nodes.some((n) => n?.type === 'room' || n?.type === 'junction')) err('needRoom')
    if (!data.nodes.some((n) => n?.type === 'exit')) err('needExit')
  }

  // --- edges ---
  const edges = []
  const edgeById = new Map()
  if (!Array.isArray(data.edges)) {
    err('edgesArray')
  } else {
    if (data.edges.length < 1 || data.edges.length > 150) err('edgesCount', { n: data.edges.length })
    const pairs = new Set()
    data.edges.forEach((e, i) => {
      if (!isObject(e)) return err('edgeObj', { i })
      if (!isNonEmptyString(e.id)) return err('edgeId', { i })
      if (edgeById.has(e.id)) return err('edgeDupId', { id: e.id })
      edgeById.set(e.id, null) // reserve the id; replaced by the edge once it validates
      const before = errors.length
      // Without a valid nodes array every endpoint would be "unknown"; report nodesArray only.
      if (Array.isArray(data.nodes)) {
        for (const end of [e.from, e.to]) {
          if (typeof end !== 'string' || !nodeById.has(end)) err('edgeEndpoint', { id: e.id, node: String(end) })
        }
      }
      if (errors.length === before && e.from === e.to) err('edgeSelf', { id: e.id })
      if (!Number.isInteger(e.cost) || e.cost <= 0) err('edgeCost', { id: e.id })
      if (errors.length !== before) return

      // Undirected: A-B and B-A are the same corridor.
      const key = e.from < e.to ? `${e.from}\u0000${e.to}` : `${e.to}\u0000${e.from}`
      if (pairs.has(key)) return err('edgeDupPair', { id: e.id, a: e.from, b: e.to })
      pairs.add(key)

      const edge = { id: e.id, from: e.from, to: e.to, cost: e.cost }
      edgeById.set(e.id, edge)
      edges.push(edge)
    })
  }

  // --- initial_state ---
  const initial = { blockedNodes: [], blockedEdges: [], closedExits: [] }
  if (!isObject(data.initial_state)) {
    err('state')
  } else {
    for (const field of STATE_FIELDS) {
      const list = data.initial_state[field]
      if (!Array.isArray(list)) {
        err('stateArray', { field })
        continue
      }
      const seen = new Set()
      for (const id of list) {
        if (seen.has(id)) continue // duplicates are harmless; keep the first
        seen.add(id)
        if (field === 'blocked_edges') {
          if (typeof id !== 'string' || !edgeById.has(id)) err('stateUnknown', { field, id: String(id) })
          else initial.blockedEdges.push(id)
          continue
        }
        const node = typeof id === 'string' ? nodeById.get(id) : undefined
        if (!node) {
          err('stateUnknown', { field, id: String(id) })
        } else if (field === 'blocked_nodes' && node.type === 'exit') {
          err('stateKind', { field, id, type: node.type })
        } else if (field === 'closed_exits' && node.type !== 'exit') {
          err('stateKind', { field, id, type: node.type })
        } else {
          const target = field === 'blocked_nodes' ? initial.blockedNodes : initial.closedExits
          target.push(id)
        }
      }
    }
  }

  if (errors.length) return { ok: false, errors }

  return {
    ok: true,
    graph: {
      building: data.building.trim(),
      nodes,
      edges,
      nodeById,
      edgeById,
      initial,
    },
  }
}

export function initialHazards(graph) {
  return {
    blockedNodes: new Set(graph.initial.blockedNodes),
    blockedEdges: new Set(graph.initial.blockedEdges),
    closedExits: new Set(graph.initial.closedExits),
  }
}

import { useI18n } from '../lib/i18n.jsx'
import { OctagonX, X } from 'lucide-react'

export default function ImportErrors({ errors, onDismiss }) {
  const { t } = useI18n()

  if (!errors || errors.length === 0) return null

  const displayedErrors = errors.slice(0, 8)
  const remainingCount = errors.length - 8

  return (
    <div className="import-errors" role="alert">
      <div className="import-errors__header">
        <div className="import-errors__title-wrap">
          <OctagonX size={18} aria-hidden="true" />
          <strong className="import-errors__title">{t('err.title')}</strong>
        </div>

        <button
          type="button"
          className="import-errors__close"
          aria-label={t('err.dismiss')}
          onClick={onDismiss}
        >
          <X size={16} aria-hidden="true" />
        </button>
      </div>

      <ul className="import-errors__list">
        {displayedErrors.map((err, idx) => (
          <li key={`${err.code}-${idx}`} className="import-errors__item">
            {t('err.' + err.code, err.params)}
          </li>
        ))}
      </ul>

      {remainingCount > 0 && (
        <div className="import-errors__more">
          {t('err.more', { n: remainingCount })}
        </div>
      )}
    </div>
  )
}

import { useMemo, useRef, useState } from 'react'
import { layoutGraph } from '../lib/layout.js'
import { useI18n } from '../lib/i18n.jsx'

const R = 20 // base node radius in canvas units (scaled by layout.k)

const toD = (ids, pos) => ids.map((id, i) => `${i ? 'L' : 'M'}${pos.get(id).x.toFixed(1)} ${pos.get(id).y.toFixed(1)}`).join(' ')

export default function MapView({ graph, hazards, result, ghostPath, highlightId, onNodeClick, onEdgeClick }) {
  const { t, num } = useI18n()
  const stageRef = useRef(null)
  const svgRef = useRef(null)
  const [hover, setHover] = useState(null)

  const layout = useMemo(() => layoutGraph(graph.nodes), [graph])
  const { pos, width, height, k } = layout
  const r = R * k

  const routeNodes = useMemo(() => new Set(result.status === 'ok' ? result.path : []), [result])
  const routeEdges = useMemo(() => new Set(result.status === 'ok' ? result.edgeIds : []), [result])
  const routeD = result.status === 'ok' ? toD(result.path, pos) : null
  const routeKey = result.status === 'ok' ? result.path.join('>') : 'none'
  const ghostD = ghostPath && ghostPath.every((id) => pos.has(id)) ? toD(ghostPath, pos) : null

  const nodeDown = (id) => {
    const node = graph.nodeById.get(id)
    return hazards.blockedNodes.has(id) || (node.type === 'exit' && hazards.closedExits.has(id))
  }

  const showTip = (id) => {
    const p = pos.get(id)
    const svg = svgRef.current
    const stage = stageRef.current
    if (!svg || !stage) return
    const box = stage.getBoundingClientRect()
    const toStage = (y) => {
      const pt = svg.createSVGPoint()
      pt.x = p.x
      pt.y = y
      const s = pt.matrixTransform(svg.getScreenCTM())
      return { x: s.x - box.left, y: s.y - box.top }
    }
    // Keep the tooltip inside the stage: clamp sideways, flip below near the top edge.
    const above = toStage(p.y - r * 1.4)
    const below = above.y < 96
    const anchor = below ? toStage(p.y + r * 1.4) : above
    const left = Math.min(Math.max(anchor.x, 130), box.width - 130)
    setHover({ id, left, top: anchor.y, below })
  }

  const activate = (handler, id) => (e) => {
    if (e.type === 'keydown' && e.key !== 'Enter' && e.key !== ' ') return
    e.preventDefault()
    handler(id)
  }

  return (
    <div className="map" ref={stageRef}>
      <svg
        ref={svgRef}
        className="map-svg"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
        role="group"
        aria-label={graph.building}
        style={{ '--k': k }}
      >
        <defs>
          <pattern id="hazard-stripes" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
            <rect width="8" height="8" fill="#3A0D12" />
            <rect width="4" height="8" fill="var(--hazard)" />
          </pattern>
          <filter id="route-glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="6" />
          </filter>
        </defs>

        {/* Corridors */}
        <g className="edges">
          {graph.edges.map((e) => {
            const a = pos.get(e.from)
            const b = pos.get(e.to)
            const blocked = hazards.blockedEdges.has(e.id)
            const unusable = !blocked && (nodeDown(e.from) || nodeDown(e.to))
            const cls = ['edge', blocked && 'is-blocked', unusable && 'is-unusable', routeEdges.has(e.id) && 'is-route']
              .filter(Boolean)
              .join(' ')
            return (
              <g key={e.id} className={cls}>
                <line className="edge__line" x1={a.x} y1={a.y} x2={b.x} y2={b.y} />
                <line
                  className="edge__hit"
                  x1={a.x}
                  y1={a.y}
                  x2={b.x}
                  y2={b.y}
                  tabIndex={0}
                  role="button"
                  aria-pressed={blocked}
                  aria-label={`${e.id} ${e.from}–${e.to}: ${t(blocked ? 'action.unblock' : 'action.block')}`}
                  onClick={activate(onEdgeClick, e.id)}
                  onKeyDown={activate(onEdgeClick, e.id)}
                />
              </g>
            )
          })}
        </g>

        {/* Previous route fading out after a reroute */}
        {ghostD && <path key={`ghost-${ghostPath.join('>')}`} className="route-ghost" d={ghostD} />}

        {/* Active route: glow, draw-in stroke, flowing dashes, one runner dot */}
        {routeD && (
          <g key={routeKey} className="route">
            <path className="route__glow" d={routeD} filter="url(#route-glow)" />
            <path className="route__line" d={routeD} pathLength="1" />
            <path className="route__flow" d={routeD} />
            <circle className="route__runner" r={6 * k} style={{ offsetPath: `path('${routeD}')` }} />
          </g>
        )}

        {/* Corridor cost labels (above the route so they stay readable) */}
        <g className="edge-labels">
          {graph.edges.map((e) => {
            const a = pos.get(e.from)
            const b = pos.get(e.to)
            const blocked = hazards.blockedEdges.has(e.id)
            const label = num(e.cost)
            const w = (label.length * 8 + 14) * Math.max(k, 0.75)
            const h = 18 * Math.max(k, 0.75)
            return (
              <g
                key={e.id}
                className={`edge-cost${blocked ? ' is-blocked' : ''}${routeEdges.has(e.id) ? ' is-route' : ''}`}
                transform={`translate(${(a.x + b.x) / 2} ${(a.y + b.y) / 2})`}
                onClick={() => onEdgeClick(e.id)}
              >
                <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={h / 2} />
                <text dy="0.35em">{blocked ? `✕ ${label}` : label}</text>
              </g>
            )
          })}
        </g>

        {/* Nodes */}
        <g className="nodes">
          {graph.nodes.map((n) => {
            const p = pos.get(n.id)
            const blocked = hazards.blockedNodes.has(n.id)
            const closed = n.type === 'exit' && hazards.closedExits.has(n.id)
            const isStart = result.startId === n.id
            const state = blocked ? 'blocked' : closed ? 'closed' : 'open'
            const cls = [
              'node',
              `node--${n.type}`,
              blocked && 'is-blocked',
              closed && 'is-closed',
              isStart && 'is-start',
              routeNodes.has(n.id) && 'is-route',
              result.exitId === n.id && result.status === 'ok' && 'is-dest',
              (highlightId === n.id || hover?.id === n.id) && 'is-hover',
            ]
              .filter(Boolean)
              .join(' ')
            return (
              <g
                key={n.id}
                className={cls}
                transform={`translate(${p.x} ${p.y})`}
                tabIndex={0}
                role="button"
                aria-label={`${n.id} ${n.label}, ${t(`type.${n.type}`)}, ${t(`state.${state}`)}`}
                onClick={activate(onNodeClick, n.id)}
                onKeyDown={activate(onNodeClick, n.id)}
                onMouseEnter={() => showTip(n.id)}
                onMouseLeave={() => setHover(null)}
                onFocus={() => showTip(n.id)}
                onBlur={() => setHover(null)}
              >
                {isStart && <circle key={`halo-${n.id}`} className="node__halo" r={r * 1.9} />}
                <g key={`${state}-${isStart}`} className="node__body">
                  <NodeShape type={n.type} r={r} />
                  <text className="node__id" dy="0.35em">
                    {n.id}
                  </text>
                  {blocked && <Badge r={r} kind="blocked" />}
                  {closed && <Badge r={r} kind="closed" />}
                </g>
                <text className="node__label" y={(n.type === 'exit' ? r * 0.95 : r) + 16 * Math.max(k, 0.7)}>
                  {n.label}
                </text>
                {isStart && (
                  <g transform={`translate(0 ${-(r + 22 * Math.max(k, 0.7))})`}>
                    <g className="pin">
                      <rect x={-48} y={-11} width={96} height={22} rx={11} />
                      <text dy="0.35em">{t('map.youAreHere')}</text>
                    </g>
                  </g>
                )}
              </g>
            )
          })}
        </g>
      </svg>

      {/* A newly imported file may not contain the hovered node. */}
      {hover && graph.nodeById.has(hover.id) && (
        <div
          className={`map-tip${hover.below ? ' is-below' : ''}`}
          style={{ left: hover.left, top: hover.top }}
          role="tooltip"
        >
          <NodeTip node={graph.nodeById.get(hover.id)} hazards={hazards} result={result} />
        </div>
      )}
    </div>
  )
}

function NodeShape({ type, r }) {
  if (type === 'exit') {
    const w = r * 2.6
    const h = r * 1.9
    return <rect className="node__shape" x={-w / 2} y={-h / 2} width={w} height={h} rx={r * 0.4} />
  }
  if (type === 'room') {
    return <rect className="node__shape" x={-r} y={-r} width={r * 2} height={r * 2} rx={r * 0.35} />
  }
  return <circle className="node__shape" r={r} />
}

function Badge({ r, kind }) {
  const cx = r * (kind === 'closed' ? 1.25 : 0.9)
  const cy = -r * 0.9
  const s = r * 0.42
  return (
    <g className={`node__badge node__badge--${kind}`} transform={`translate(${cx} ${cy})`}>
      <circle r={s} />
      {kind === 'blocked' ? (
        <path d={`M${-s * 0.4} ${-s * 0.4}L${s * 0.4} ${s * 0.4}M${s * 0.4} ${-s * 0.4}L${-s * 0.4} ${s * 0.4}`} />
      ) : (
        <path
          d={`M${-s * 0.42} ${-s * 0.05}h${s * 0.84}v${s * 0.6}h${-s * 0.84}z M${-s * 0.25} ${-s * 0.05}v${-s * 0.25}a${s * 0.25} ${s * 0.25} 0 0 1 ${s * 0.5} 0v${s * 0.25}`}
        />
      )}
    </g>
  )
}

function NodeTip({ node, hazards, result }) {
  const { t, num } = useI18n()
  const blocked = hazards.blockedNodes.has(node.id)
  const closed = node.type === 'exit' && hazards.closedExits.has(node.id)
  const state = blocked ? 'blocked' : closed ? 'closed' : 'open'
  const cost = result.costs?.get(node.id)
  return (
    <>
      <div className="map-tip__title">
        <span className="mono">{node.id}</span> {node.label}
      </div>
      <div className="map-tip__meta">
        {t(`type.${node.type}`)} · <span className={`map-tip__state is-${state}`}>{t(`state.${state}`)}</span>
      </div>
      {result.startId && result.status !== 'start-blocked' && (
        <div className="map-tip__meta">
          {t('map.costFromStart')}: <span className="mono">{cost === undefined ? t('map.unreachable') : num(cost)}</span>
        </div>
      )}
    </>
  )
}

import { useI18n } from '../lib/i18n.jsx'
import { MapPin, RotateCcw } from 'lucide-react'

export default function HazardPanel({
  graph,
  hazards,
  startId,
  onSetStart,
  onToggleNode,
  onToggleEdge,
  onToggleExit,
  onReset,
}) {
  const { t, num } = useI18n()

  const nodes = graph?.nodes || []
  const edges = graph?.edges || []

  const roomAndJunctionNodes = nodes.filter(
    (n) => n.type === 'room' || n.type === 'junction'
  )
  const exitNodes = nodes.filter((n) => n.type === 'exit')

  const blockedNodes = hazards?.blockedNodes || new Set()
  const blockedEdges = hazards?.blockedEdges || new Set()
  const closedExits = hazards?.closedExits || new Set()

  const activeNodesCount = roomAndJunctionNodes.filter((n) => blockedNodes.has(n.id)).length
  const activeEdgesCount = edges.filter((e) => blockedEdges.has(e.id)).length
  const activeExitsCount = exitNodes.filter((n) => closedExits.has(n.id)).length
  const totalHazards = blockedNodes.size + blockedEdges.size + closedExits.size

  return (
    <div className="card hazard-panel">
      {/* Starting Location Picker */}
      <div className="hazard-panel__select-wrap">
        <label htmlFor="hazard-panel-start-select" className="section-title">
          {t('panel.start')}
        </label>
        <select
          id="hazard-panel-start-select"
          className="hazard-panel__select"
          value={startId ?? ''}
          onChange={(e) => onSetStart?.(e.target.value)}
        >
          <option value="" disabled>
            {t('panel.startPlaceholder')}
          </option>
          {roomAndJunctionNodes.map((n) => {
            const isBlocked = blockedNodes.has(n.id)
            return (
              <option key={n.id} value={n.id} disabled={isBlocked}>
                {`${n.id} — ${n.label}${isBlocked ? ` · ${t('state.blocked')}` : ''}`}
              </option>
            )
          })}
        </select>
      </div>

      {/* Hazards Section Header */}
      <div className="hazard-panel__header">
        <div className="hazard-panel__header-left">
          <span className="section-title">{t('panel.hazards')}</span>
          <span className={`badge ${totalHazards > 0 ? 'badge--hazard' : ''}`}>
            {t('panel.activeHazards', { n: totalHazards })}
          </span>
        </div>
        <button type="button" className="btn btn-ghost" onClick={onReset}>
          <RotateCcw size={14} aria-hidden="true" />
          <span>{t('panel.reset')}</span>
        </button>
      </div>

      {/* 1. Rooms & Junctions */}
      <details open className="hazard-group">
        <summary className="hazard-group__summary">
          <span>{t('panel.nodes')}</span>
          <span className={`badge ${activeNodesCount > 0 ? 'badge--hazard' : ''}`}>
            {num(activeNodesCount)}
          </span>
        </summary>
        <div className="hazard-group__body">
          {roomAndJunctionNodes.map((n) => {
            const isBlocked = blockedNodes.has(n.id)
            const isStart = n.id === startId

            return (
              <div
                key={n.id}
                className={`hazard-row ${isBlocked ? 'hazard-row--active-hazard' : ''}`}
              >
                <div className="hazard-row__left">
                  {isStart && (
                    <MapPin
                      size={14}
                      className="hazard-row__start-icon"
                      aria-label={t('route.start')}
                    />
                  )}
                  <span className="hazard-row__id">{n.id}</span>
                  <span className="hazard-row__label">{n.label}</span>
                </div>

                <div className="hazard-row__right">
                  <span
                    className={`hazard-row__state ${
                      isBlocked ? 'hazard-row__state--blocked' : 'hazard-row__state--open'
                    }`}
                  >
                    {t(isBlocked ? 'state.blocked' : 'state.open')}
                  </span>
                  <button
                    type="button"
                    role="switch"
                    aria-checked={isBlocked}
                    aria-label={t(isBlocked ? 'action.unblock' : 'action.block')}
                    className={`toggle-switch ${isBlocked ? 'toggle-switch--hazard' : ''}`}
                    onClick={() => onToggleNode?.(n.id)}
                  >
                    <span className="toggle-switch__knob" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      </details>

      {/* 2. Corridors (scrollable for up to 150) */}
      <details open className="hazard-group">
        <summary className="hazard-group__summary">
          <span>{t('panel.corridors')}</span>
          <span className={`badge ${activeEdgesCount > 0 ? 'badge--hazard' : ''}`}>
            {num(activeEdgesCount)}
          </span>
        </summary>
        <div className="hazard-group__body hazard-group__body--scrollable">
          {edges.map((edge) => {
            const isBlocked = blockedEdges.has(edge.id)

            return (
              <div
                key={edge.id}
                className={`hazard-row ${isBlocked ? 'hazard-row--active-hazard' : ''}`}
              >
                <div className="hazard-row__left">
                  <span className="hazard-row__id">{edge.id}</span>
                  <span className="hazard-row__label">
                    {edge.from} ↔ {edge.to}
                  </span>
                  <span className="chip">{num(edge.cost)}</span>
                </div>

                <div className="hazard-row__right">
                  <span
                    className={`hazard-row__state ${
                      isBlocked ? 'hazard-row__state--blocked' : 'hazard-row__state--open'
                    }`}
                  >
                    {t(isBlocked ? 'state.blocked' : 'state.open')}
                  </span>
                  <button
                    type="button"
                    role="switch"
                    aria-checked={isBlocked}
                    aria-label={t(isBlocked ? 'action.unblock' : 'action.block')}
                    className={`toggle-switch ${isBlocked ? 'toggle-switch--hazard' : ''}`}
                    onClick={() => onToggleEdge?.(edge.id)}
                  >
                    <span className="toggle-switch__knob" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      </details>

      {/* 3. Exits */}
      <details open className="hazard-group">
        <summary className="hazard-group__summary">
          <span>{t('panel.exits')}</span>
          <span className={`badge ${activeExitsCount > 0 ? 'badge--warn' : ''}`}>
            {num(activeExitsCount)}
          </span>
        </summary>
        <div className="hazard-group__body">
          {exitNodes.map((n) => {
            const isClosed = closedExits.has(n.id)

            return (
              <div
                key={n.id}
                className={`hazard-row ${isClosed ? 'hazard-row--active-warn' : ''}`}
              >
                <div className="hazard-row__left">
                  <span className="hazard-row__id">{n.id}</span>
                  <span className="hazard-row__label">{n.label}</span>
                </div>

                <div className="hazard-row__right">
                  <span
                    className={`hazard-row__state ${
                      isClosed ? 'hazard-row__state--closed' : 'hazard-row__state--open'
                    }`}
                  >
                    {t(isClosed ? 'state.closed' : 'state.open')}
                  </span>
                  <button
                    type="button"
                    role="switch"
                    aria-checked={isClosed}
                    aria-label={t(isClosed ? 'action.reopen' : 'action.close')}
                    className={`toggle-switch ${isClosed ? 'toggle-switch--warn' : ''}`}
                    onClick={() => onToggleExit?.(n.id)}
                  >
                    <span className="toggle-switch__knob" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      </details>
    </div>
  )
}

